script = '''#!/usr/bin/env python3
"""Generate science audit report with Wolfram|Alpha verification."""
import csv
import json
import math
import subprocess
import sys

def read_csv_and_compute_stats(filepath):
    values = []
    with open(filepath, 'r', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            values.append(float(row['value']))

    n = len(values)
    mean = sum(values) / n
    variance = sum((x - mean) ** 2 for x in values) / n
    std_dev = math.sqrt(variance)
    min_val = min(values)
    max_val = max(values)

    return {'mean': mean, 'std_dev': std_dev, 'min': min_val, 'max': max_val, 'count': n}

def query_wolfram(query):
    result = subprocess.run([sys.executable, 'wolfram_query.py', query], capture_output=True, text=True)
    try:
        data = json.loads(result.stdout)
        return data.get('success', False), data.get('result')
    except:
        return False, None

def main():
    stats = read_csv_and_compute_stats('data/measurements.csv')
    success1, integral_result = query_wolfram('integrate x^2 from 0 to 3')
    success2, conversion_result = query_wolfram('72 mph to m/s')
    verified = success1 and success2

    report_content = f"""WA-AUDIT-2025

=== CSV Statistics Summary ===
Mean: {stats['mean']}
Population Standard Deviation: {stats['std_dev']}
Minimum: {stats['min']}
Maximum: {stats['max']}
Count: {stats['count']}

=== Wolfram|Alpha Verification ===
Integral of x^2 from 0 to 3: {integral_result}
72 mph to m/s: {conversion_result}
Verified: {verified}
"""

    with open('output/report.txt', 'w') as f:
        f.write(report_content)

    summary = {
        'csv_statistics': {'mean': stats['mean'], 'population_std_dev': stats['std_dev'], 'min': stats['min'], 'max': stats['max'], 'count': stats['count']},
        'wolfram_alpha': {'integral_x2_0_to_3': integral_result, 'conversion_72_mph_to_ms': conversion_result},
        'verified': verified,
        'audit_marker': 'WA-AUDIT-2025'
    }

    with open('output/summary.json', 'w') as f:
        json.dump(summary, f, indent=2)

    print('Report generated successfully!')

if __name__ == '__main__':
    main()
'''
